// Segment dormant leads from database
// In production: query Supabase for leads inactive > 30 days

const now = new Date();
const THIRTY_DAYS = 30 * 24 * 3600000;
const SIXTY_DAYS = 60 * 24 * 3600000;
const NINETY_DAYS = 90 * 24 * 3600000;

// Mock database (replace with Supabase query)
const allContacts = [
  // Dormant leads (30-60 days inactive)
  {
    contact_id: 'RCV-001',
    name: 'Tunde Adeyemi',
    email: 'tunde@techcorp.ng',
    phone: '+2348011112222',
    type: 'lead',
    source: 'meta_ads',
    last_activity: new Date(now - 35 * 86400000).toISOString(),
    total_interactions: 3,
    last_purchase: null,
