    total_interactions: 8,
    last_purchase: new Date(now - 120 * 86400000).toISOString(),
    lifetime_value: 350000,
    tags: ['fashion', 'repeat_buyer']
  },
  {
    contact_id: 'RCV-003',
    name: 'Yusuf Abdullahi',
    email: 'yusuf@tradingco.ng',
    phone: '+2348055556666',
    type: 'dormant_lead',
    source: 'whatsapp',
    last_activity: new Date(now - 75 * 86400000).toISOString(),
    total_interactions: 2,
    last_purchase: null,
    lifetime_value: 0,
    tags: ['logistics', 'interstate']
  },
  {
    contact_id: 'RCV-004',
    name: 'Blessing Eze',
    email: 'blessing@realestate.ng',
    phone: '+2348077778888',
    type: 'previous_customer',
    source: 'referral',
    last_activity: new Date(now - 95 * 86400000).toISOString(),
    total_interactions: 12,
    last_purchase: new Date(now - 180 * 86400000).toISOString(),
    lifetime_value: 750000,
    tags: ['real_estate', 'high_value']
  },
  {
    contact_id: 'RCV-005',
    name: 'Kola Martins',
    email: 'kola@logistics.ng',
    phone: '+2348099990000',
    type: 'dormant_lead',
    source: 'website',
    last_activity: new Date(now - 150 * 86400000).toISOString(),
    total_interactions: 1,
    last_purchase: null,
    lifetime_value: 0,
    tags: ['logistics', 'new']
  }
];

// Segment contacts
const segments = {
  warm_dormant: [],    // 30-60 days
  cold_dormant: [],    // 60-90 days
  frozen: [],          // 90+ days
  high_value: []       // Any dormant with lifetime_value > 100000
};

for (const contact of allContacts) {
  const daysSinceActivity = (now - new Date(contact.last_activity)) / 86400000;

  if (contact.lifetime_value > 100000) {
    segments.high_value.push({ ...contact, days_inactive: Math.floor(daysSinceActivity), segment: 'high_value' });
  }

  if (daysSinceActivity >= 90) {
    segments.frozen.push({ ...contact, days_inactive: Math.floor(daysSinceActivity), segment: 'frozen' });
  } else if (daysSinceActivity >= 60) {
    segments.cold_dormant.push({ ...contact, days_inactive: Math.floor(daysSinceActivity), segment: 'cold_dormant' });
  } else if (daysSinceActivity >= 30) {
    segments.warm_dormant.push({ ...contact, days_inactive: Math.floor(daysSinceActivity), segment: 'warm_dormant' });
  }
}

// Return all contacts that need reactivation
const needsReactivation = [
  ...segments.high_value,
  ...segments.frozen,
  ...segments.cold_dormant,
  ...segments.warm_dormant
].filter((contact, index, self) => 
  index === self.findIndex(c => c.contact_id === contact.contact_id)
);

if (needsReactivation.length === 0) {
  return [{ json: { status: 'no_dormant_contacts', count: 0 } }];
}

return needsReactivation.map(contact => ({ json: contact }));

// Generate personalized reactivation message based on segment and history
const contact = $input.first().json;

let whatsappMessage = '';
let emailSubject = '';
let emailBody = '';
let campaignType = '';
let channel = 'whatsapp';

switch (contact.segment) {
  case 'high_value':
    campaignType = 'VIP_RECOVERY';
    whatsappMessage = `Hi ${contact.name}! 👋\n\nIt's been a while since we last worked together. As one of our valued clients, we wanted to personally reach out.\n\nWe've made some exciting updates to our services that I think you'd love. Would you be open to a quick chat this week?\n\nBest regards,\nThe Jules Luxury Team`;
    emailSubject = `We miss working with you, ${contact.name}`;
    emailBody = `Hi ${contact.name},<br><br>It's been ${contact.days_inactive} days since we last connected, and we wanted to reach out personally.<br><br>As a valued client, your experience matters to us. We've been making some exciting improvements and would love to show you what's new.<br><br>Would you have 15 minutes this week for a catch-up call?<br><br>Best regards,<br>Jules Luxury Team`;
    break;

  case 'frozen':
    campaignType = 'REACTIVATION';
    channel = 'email';
    whatsappMessage = null;
    emailSubject = `We'd love to reconnect - ${contact.name}`;
    emailBody = `Hi ${contact.name},<br><br>It's been a while! We noticed you haven't been active recently and wanted to check in.<br><br>Whether your needs have changed or you simply got busy, we're here when you're ready.<br><br>As a special offer, we're providing a 10% discount on your next service. Just reply to this email to claim it.<br><br>Best regards,<br>Jules Luxury Team`;
    break;

  case 'cold_dormant':
    campaignType = 'NURTURE';
    whatsappMessage = `Hi ${contact.name}! 😊\n\nHope you're doing well! We've been sharing some helpful content lately about logistics optimization. Thought you might find it useful.\n\nWould you like us to send you our latest guide? Just reply YES!\n\n- Jules Luxury Team`;
    emailSubject = `Helpful resources for you - ${contact.name}`;
    emailBody = `Hi ${contact.name},<br><br>We've been working on some great resources that might help your business. Here are a few highlights:<br><br>• Logistics cost optimization guide<br>• Delivery efficiency checklist<br>• Customer retention strategies<br><br>Would you like us to send these to you?<br><br>Best regards,<br>Jules Luxury Team`;
    break;

  case 'warm_dormant':
    campaignType = 'GENTLE_REMINDER';
    whatsappMessage = `Hi ${contact.name}! 👋\n\nJust a friendly check-in! We haven't heard from you in a while and wanted to make sure everything is going well.\n\nIs there anything we can help you with? We're just a message away!\n\n- Jules Luxury Team`;
    emailSubject = `Just checking in - ${contact.name}`;
    emailBody = `Hi ${contact.name},<br><br>Just a quick note to say hello! We hope everything is going well with your business.<br><br>If you need anything - from logistics support to a simple chat about your needs - we're here.<br><br>Best regards,<br>Jules Luxury Team`;
    break;
}

return [{
  json: {
    ...contact,
    campaign_type: campaignType,
    channel: channel,
    whatsapp_message: whatsappMessage,
    email_subject: emailSubject,
    email_body: emailBody,
    generated_at: new Date().toISOString()
  }
}];

// Create campaign entry and schedule follow-up
const contact = $input.first().json;

const campaignEntry = {
  campaign_id: `CAMP-${Date.now()}-${contact.contact_id}`,
  contact_id: contact.contact_id,
  name: contact.name,
  email: contact.email,
  phone: contact.phone,
  campaign_type: contact.campaign_type,
  segment: contact.segment,
  channel: contact.channel,
  status: 'sent',
  sent_at: new Date().toISOString(),
  response_received: false,
  follow_up_scheduled: true,
  follow_up_at: new Date(Date.now() + 7 * 86400000).toISOString(),
  conversion_tracked: false,
  notes: []
};

return [{ json: campaignEntry }];

// Generate analytics and summary
const contact = $input.first().json;

const summary = {
  campaign_id: contact.campaign_id,
  contact: contact.name,
  segment: contact.segment,
  campaign_type: contact.campaign_type,
  channel: contact.channel,
  days_inactive: contact.days_inactive,
  lifetime_value: contact.lifetime_value,
  potential_revenue: contact.lifetime_value > 0 ? contact.lifetime_value * 0.3 : 150000,
  status: 'reactivation_sent',
  next_action: 'wait_for_response',
  follow_up_date: contact.follow_up_at,
  timestamp: new Date().toISOString()
};

return [{ json: summary }];

// Process reactivation response
const response = $input.first().json.body;

const result = {
  contact_id: response.contact_id,
  response_type: 'reactivation_replied',
  response_channel: response.channel || 'whatsapp',
  response_message: response.message || '',
  sentiment: response.message?.toLowerCase().includes('yes') || response.message?.toLowerCase().includes('interested') ? 'positive' : 'neutral',
  handoff_to_sales: true,
  priority: response.lifetime_value > 100000 ? 'high' : 'normal',
  timestamp: new Date().toISOString()
};

return [{ json: result }];

// No dormant contacts found
return [{
  json: {
    status: 'no_dormant_contacts',
    message: 'All contacts are active. No reactivation needed.',
    checked_at: new Date().toISOString()
  }
}];
